// Ticker lookup
async function lookupTicker(){
  const t = document.getElementById('ticker-input').value.trim().toUpperCase();
  if(!t) return;
  const res = document.getElementById('ticker-result');
  res.innerHTML = '<span class="loading">Loading '+t+'…</span>';
