    const dnames = Object.keys(doms);
    res.innerHTML = '<p style="margin-bottom:8px"><span class="ticker" style="font-size:1.2rem">'+t+'</span> <span class="badge t360">'+data.coverage_count+' domains</span></p>' +
      '<div class="t360bar" style="margin-bottom:12px">'+dnames.map(n=>'<span>'+n+'</span>').join('')+'</div>' +
      dnames.map(n=>{
        const dd = doms[n];
        const td = dd.data||{};
        return '<details class="audit" style="margin-bottom:6px"><summary>'+n+' <span style="color:var(--mut)">as of '+ago(dd.as_of)+'</span></summary><pre>'+JSON.stringify(td,null,1).slice(0,1000)+'</pre></details>';
