// Ticker lookup: received JSON remains reported research, never investment authority.
let tickerLookupGeneration = 0;
const tickerSelection = () => document.getElementById('ticker-input').value.trim().toUpperCase();
function tickerText(tag, text, className='') {
  const node = document.createElement(tag);
  node.textContent = text;
  node.className = className;
  return node;
}
function tickerAudit(label, value) {
  const details = document.createElement('details');
  details.className = 'audit';
  details.appendChild(tickerText('summary', label));
  // Serialize on expansion; the complete received value stays in this closure.
  // Large packets do not create a hidden, duplicated DOM on every lookup.
  details.addEventListener('toggle', () => {
    if (!details.open || details.dataset.loaded) return;
    const pre = tickerText('pre', JSON.stringify(value, null, 2));
    pre.tabIndex = 0;
    pre.setAttribute('aria-label', label);
    details.appendChild(pre);
    details.dataset.loaded = 'true';
  });
  return details;
}
function tickerResult(packet, symbol) {
  const result = document.createDocumentFragment();
  result.appendChild(tickerText('p', symbol, 'ticker lookup-symbol'));
  // This is the parsed received JSON, not a hash-qualified source original.
  result.appendChild(tickerAudit('Complete received packet (parsed JSON)', packet));
  let inventory;
  try { inventory = objectMap(objectMap(packet).tickers); }
  catch (_) {
    result.appendChild(tickerText('p', 'Unavailable: missing or invalid ticker inventory.', 'err'));
    return result;
  }
  result.appendChild(tickerText('p', 'Packet timestamp '+ago(packet.generated_at)+'. Observation freshness and investment validity are unverified.', 'meta'));
  if (!Object.hasOwn(inventory, symbol)) {
    result.appendChild(tickerText('p', 'No record for '+symbol+' in the received inventory ('+Object.keys(inventory).length+' ticker keys).', 'err'));
    return result;
  }
  const record = inventory[symbol];
  result.appendChild(tickerAudit('Complete received ticker record', record));
  let domains;
  try { domains = objectMap(objectMap(record).domains); }
  catch (_) {
    result.appendChild(tickerText('p', 'Unavailable: missing or invalid ticker record or domain map.', 'err'));
    return result;
  }
  const names = Object.keys(domains), reported = countText(record.coverage_count);
  result.appendChild(tickerText('p', reported+' reported domains; '+names.length+' received domain entries. These are not independent votes.', 'meta'));
  if (reported === 'Unavailable' || record.coverage_count !== names.length) {
    result.appendChild(tickerText('p', 'Coverage count is missing, invalid or inconsistent with the received domain map.', 'err'));
  }
  for (const name of names) {
    const domain = domains[name];
    const valid = domain !== null && typeof domain === 'object' && !Array.isArray(domain);
    const label = name+' — '+(valid ? 'reported as of '+ago(domain.as_of) : 'invalid domain record; original value retained');
    result.appendChild(tickerAudit(label, domain));
  }
  if (!names.length) result.appendChild(tickerText('p', 'No domain entries received.', 'meta'));
  return result;
}
function tickerStatus(message, className='') {
  document.getElementById('ticker-status').textContent = message;
  document.getElementById('ticker-status').className = className;
}
function invalidateTickerLookup() {
  tickerLookupGeneration++;
  document.getElementById('ticker-result').replaceChildren();
  document.getElementById('ticker-result').setAttribute('aria-busy', 'false');
  tickerStatus('Selection changed. Submit a lookup to inspect its received record.');
}
async function lookupTicker() {
  const symbol = tickerSelection(), generation = ++tickerLookupGeneration;
  const result = document.getElementById('ticker-result');
  const current = () => generation === tickerLookupGeneration && symbol === tickerSelection();
  result.replaceChildren();
  result.setAttribute('aria-busy', 'false');
  if (!symbol) { tickerStatus('Enter a ticker to look up.'); return; }
  result.setAttribute('aria-busy', 'true');
  tickerStatus('Loading '+symbol+'…', 'loading');
  try {
    const packet = await get('data/ticker-360.json');
    if (!current()) return;
    result.replaceChildren(tickerResult(packet, symbol));
    tickerStatus('Lookup completed for '+symbol+'.');
  } catch (error) {
    if (!current()) return;
    tickerStatus('Lookup unavailable: '+(typeof error?.message === 'string' ? error.message : 'request failed'), 'err');
  } finally {
    if (current()) result.setAttribute('aria-busy', 'false');
  }
}
document.getElementById('ticker-form').addEventListener('submit', event => { event.preventDefault(); lookupTicker(); });
document.getElementById('ticker-input').addEventListener('input', invalidateTickerLookup);
